// BuffLoad is the read (mas-bandwidth/schema docs/SPEC-TABLES.md §4, §6.5): it returns the whole value, or
// refuses with value at its defaults and false. A supplied report receives this
// read's report, and on a refusal report.Err() is the typed reason. The open
// checks every condition the wire alone decides; the body read checks this
// declaration's (tla/ReadOrder.tla, OneVerdict).
func BuffLoad(value *BuffRow, data []byte, report *TableReport) bool {
	read := report
	if read == nil {
		read = &TableReport{}
	} else {
		*read = TableReport{}
	}
	r, verdict := tableOpenChecked(data, read)
	if verdict != TableOpenOk || !BuffLoadBody(&r, value) || r.Offset != int64(len(r.Buffer)) || read.Refused() {
		tableRefused(read)
		BuffReset(value)
		return false
	}
	return true
}

// BuffReadStrict is BuffLoad under a second spelling (mas-bandwidth/schema docs/SPEC-TABLES.md §6.5): the value, or the typed reason.
func BuffReadStrict(wire []byte) (*BuffRow, error) {
	value := &BuffRow{}
	var report TableReport
	if !BuffLoad(value, wire, &report) {
		return nil, report.Err()
	}
	return value, nil
}

func BuffMeasureBodyRetain(value *BuffRow, ids *TableRetainIds) int64 {
	w := TableRetainWriter{Measuring: true, Ids: ids}
	if !BuffSaveBodyRetain(&w, value) {
		return -1
	}
	return w.Offset
}

func BuffSaveBodyRetain(w *TableRetainWriter, value *BuffRow) bool {
	if !BuffSaveBodyFieldsRetain(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func BuffSaveBodyFieldsRetain(w *TableRetainWriter, value *BuffRow) bool {
	{
		if math.Float32bits(value.Multiplier) != math.Float32bits(1.0) {
			if ref := w.Ids.refAtHit(79, 0x9adc623a805c87c6); !w.headerPair(ref, 10) {
				w.headerRest(ref, 10)
			}
			if value.Multiplier-value.Multiplier != 0 {
				return false
			}
			w.Put32(math.Float32bits(value.Multiplier))
		}
	}
	if !tableRetainTail(w) {
		return false
	}
	return !w.Overflow && !w.Ids.Overflow
}

func BuffLoadBodyRetain(r *TableRetainReader, value *BuffRow) bool {
	BuffReset(value)
	r.Retain.discard(r.Path, false, 0)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Refuse(TableRefuseWireDamaged, "")
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Refuse(TableRefuseWireDamaged, "")
			return false
		}
		kind := r.Get8()
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Refuse(TableRefuseWireDamaged, "")
			return false
		}
		switch fieldID {
		case 0x9adc623a805c87c6: // multiplier
			if kind != 10 {
				r.Report.Refuse(TableRefuseKindMismatch, "Buff.multiplier")
				return false
			}
			if !r.Has(4) {
				r.Report.Refuse(TableRefuseWireDamaged, "")
				return false
			}
			{
				b := r.Get32()
				if b&0x7f800000 == 0x7f800000 {
					r.Report.Refuse(TableRefuseNonFiniteFloat, "Buff.multiplier")
					r.Report.Refuse(TableRefuseWireDamaged, "")
					return false
				} else {
					v := math.Float32frombits(b)
					value.Multiplier = v
				}
			}
		default:
			r.Report.Unknown++
			if !r.capture(fieldID, kind, "Buff") {
				r.Report.Refuse(TableRefuseWireDamaged, "")
				return false
			}
		}
	}
}

// DebuffReset restores Debuff's declared defaults in place, reusing the storage
// the value already holds. The reader calls it before overlaying.
func DebuffReset(value *DebuffRow) {
	value.Amount = 0
}

func DebuffMeasureBody(value *DebuffRow, ids *TableIds) int64 {
	bytes := int64(1)
	if (value.Amount != 0) && (value.Amount < 0 || value.Amount > 100) {
		return -1
	}
	if value.Amount != 0 {
		bytes += tableLebBytes(ids.refAtHit(69, 0x8113fe7ea2b16969)) + 1 + 4
	} // amount
	if ids.Overflow {
		return -1
	}
	return bytes
}

func DebuffMeasure(value *DebuffRow) int64 {
	var ids TableIds
	body := DebuffMeasureBody(value, &ids)
	if body < 0 || ids.Overflow {
		return -1
	}
	return 1 + body + int64(ids.Count)*8 + 8
}

func DebuffMeasureReason(value *DebuffRow) (int64, error) {
	size := DebuffMeasure(value)
	if size < 0 {
		return size, TableRefuseInvalidValue
	}
	return size, nil
}
func DebuffSaveBody(w *TableWriter, value *DebuffRow) bool {
	if !DebuffSaveBodyFields(w, value) {
		return false
	}
	w.Put8(0)
	return !w.Overflow && !w.Ids.Overflow
}
func DebuffSaveBodyFields(w *TableWriter, value *DebuffRow) bool {
	{
		if value.Amount != 0 {
			if ref := w.Ids.refAtHit(69, 0x8113fe7ea2b16969); !w.headerPair(ref, 4) {
				w.headerRest(ref, 4)
			}
			if value.Amount < 0 || value.Amount > 100 {
				return false
			}
			w.Put32(uint32(value.Amount))
		}
	}
	return !w.Overflow && !w.Ids.Overflow
}

func DebuffSave(value *DebuffRow, buffer []byte) int64 {
	var ids TableIds
	w := TableWriter{Buffer: buffer, Ids: &ids}
	w.Put8(1)
	if !DebuffSaveBody(&w, value) {
		return -1
	}
	w.Trailer()
	if w.Overflow || ids.Overflow {
		return -1
	}
	return w.Offset
}

func DebuffLoadBody(r *TableReader, value *DebuffRow) bool {
	DebuffReset(value)
	for {
		ref, ok := r.lebPair()
		if !ok {
			ref, ok = r.lebWide()
		}
		if !ok {
			r.Report.Refuse(TableRefuseWireDamaged, "")
			return false
		}
		if ref == 0 {
			return true
		}
		fieldID, ok := r.Resolve(ref)
		if !ok || !r.Has(1) {
			r.Report.Refuse(TableRefuseWireDamaged, "")
			return false
		}
		kind := r.Get8()
		if fieldID == 0xfffffffffffffffe || fieldID == 0xfffffffffffffffd || r.Nested && fieldID == 0xffffffffffffffff {
			r.Report.Refuse(TableRefuseWireDamaged, "")
			return false
		}
		switch fieldID {
		case 0x8113fe7ea2b16969: // amount
			if kind != 4 {
				if tableKindWidens(kind, 4) {
					if !r.Has(tableKindBytes(kind)) {
						r.Report.Refuse(TableRefuseWireDamaged, "")
						return false
					}
					{
						v := r.Signed(kind)
						if v < 0 || v > 100 {
							r.Report.Refuse(TableRefuseOutOfRange, "Debuff.amount")
							r.Report.Refuse(TableRefuseWireDamaged, "")
							return false
						}
						value.Amount = int32(v)
					}
					r.Report.Widened++
					break
				}
				r.Report.Refuse(TableRefuseKindMismatch, "Debuff.amount")
				return false
			}
			if !r.Has(4) {
				r.Report.Refuse(TableRefuseWireDamaged, "")
				return false
			}
			{
				v := int32(r.Get32())
				if v < 0 || v > 100 {
					r.Report.Refuse(TableRefuseOutOfRange, "Debuff.amount")
					r.Report.Refuse(TableRefuseWireDamaged, "")
					return false
				}
				value.Amount = int32(v)
			}
		default:
			r.Report.Unknown++
			if !r.Skip(kind) {
				r.Report.Refuse(TableRefuseWireDamaged, "")
				return false
			}
		}
	}
}

